    mutex_unlock(&sk->sk_lock);
    return ret;
}

int nl_dump(struct sock *sk)
{
    struct sk_buff *skb = NULL;
    int err = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_data_input && sk->sk_data_input(sk)) {
        err = -EBUSY;
        goto unlock_mutex;
    }

    skb = alloc_skb(NLMSG_SPACE(4096), GFP_KERNEL);
    if (!skb) {
        err = -ENOMEM;
        goto unlock_mutex;
    }

    err = sk->sk_user_data ? ((struct nl_cb_ops *)sk->sk_user_data)->dump(skb) : -EINVAL;
    if (err < 0)
        goto free_skb;

    if (skb->len > 0) {
        if (sk_filter(sk)) {
            sk_filter(sk, skb);
            err = 0;
        } else {
            err = netlink_unicast(sk, skb, 0, MSG_DONTWAIT);
        }
    } else {
        kfree_skb(skb);
        skb = NULL;
        err = 0;
    }

free_skb:
    if (!err)
        kfree_skb(skb);
unlock_mutex:
    mutex_unlock(&sk->sk_mutex);
    return err;
}

int netlink_dump(struct sock *sk)
{
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->netlink_mutex);
    if (sk->protinfo.af_netlink.cb_running) {
        mutex_unlock(&sk->netlink_mutex);
        return -EBUSY;
    }

    skb = alloc_skb(4096, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&sk->netlink_mutex);
        return -ENOMEM;
    }

    sk->protinfo.af_netlink.cb_running = true;
    err = sk->protinfo.af_netlink.dump(skb, sk);
    sk->protinfo.af_netlink.cb_running = false;

    if (!err) {
        if (sk->protinfo.af_netlink.filters) {
            err = netlink_unicast(sk, skb, sk->protinfo.af_netlink.dst_port);
        } else {
            kfree_skb(skb);
        }
    } else {
        kfree_skb(skb);
    }

    mutex_unlock(&sk->netlink_mutex);
    return err;
}

int netlink_dump(struct sock *sk)
{
    struct sk_buff *skb = NULL;
    int ret = 0;

    mutex_lock(&sk->sk_netlink_lock);
    if (sk->sk_netlink_dump_running) {
        ret = -EBUSY;
        goto unlock;
    }

    if (!sk->sk_netlink_mem_available) {
        ret = -ENOMEM;
        goto unlock;
    }

    skb = alloc_skb(sk->sk_netlink_msg_size, GFP_KERNEL);
    if (!skb) {
        ret = -ENOMEM;
        goto unlock;
    }

    sk->sk_netlink_dump_running = true;
    ret = sk->sk_netlink_dump(skb);
    sk->sk_netlink_dump_running = false;

    if (ret < 0) {
        kfree_skb(skb);
        goto unlock;
    }

    if (sk->sk_netlink_filters && sk->sk_netlink_filters(skb))
        ret = netlink_send(skb);
    else
        kfree_skb(skb);

unlock:
    mutex_unlock(&sk->sk_netlink_lock);
    return ret;
}
